script:
frappe.ui.form.on('Customer', {
    refresh(frm) {
        frm.events.toggle_mandatory_fields(frm);
    },
    
    naming_series(frm) {
        frm.events.toggle_mandatory_fields(frm);
    },

    toggle_mandatory_fields(frm) {
        frm.set_df_property('custom_dksh_customer_code', 'reqd', 0);
        frm.set_df_property('custom_cd_customer_code', 'reqd', 0);

        if (frm.doc.naming_series === 'DKSH-CODE') {
            frm.set_df_property('custom_dksh_customer_code', 'reqd', 1);
        } 
        else if (frm.doc.naming_series === 'CD-CODE') {
            frm.set_df_property('custom_cd_customer_code', 'reqd', 1);
        }
    }
});
